class stringx
{
public:
	void* data_;
	stringx(const char*, int = -1);
	stringx(const stringx&);
	~stringx();
	const char* data() const { return *(const char**)this; }
	int length() const { return *(int*)((char*)data_ + 8); }
	void remove_leading(const char*);
	void remove_trailing(const char*);
	void remove_surrounding_whitespace()
	{
		remove_leading(" \t\n\r");
		remove_trailing(" \t\n\r");
	}
};

class FEMenuEntry;
class entity;
class PanelQuad;

class TextString
{
public:
	virtual ~TextString();
	virtual void Draw();
	virtual void changeText(stringx);
	virtual void changePos(float, float);
	virtual void changeScale(float);
	virtual void changeColor(unsigned int);
	virtual stringx getText();
};

class FEMenu
{
	char menu_storage[96];
protected:
	FEMenu* parent;
	char menu_tail[128];
public:
	virtual ~FEMenu();
	virtual void Load();
	virtual void Update(float);
	virtual void Select(int);
	virtual void Draw();
	virtual void OnActivate();
	virtual void OnUp(int);
	virtual void OnDown(int);
	virtual void OnLeft(int);
	virtual void OnRight(int);
	virtual void OnTriangle(int);
	virtual void OnCross(int);
	virtual void OnStart(int);
	virtual void MakeActive(FEMenu*, bool = true);
};

class FEMultiMenu : public FEMenu
{
public:
	virtual void setHigh(FEMenuEntry*, bool = true);
};

class Career
{
public:
	void SetInitials(stringx);
};

enum EventType
{
	SS_FE_ONX = 24,
	SS_FE_ERROR = 28
};

class SoundScriptManager
{
public:
	static SoundScriptManager* inst();
	void unpause();
	void pause();
	void playEvent(EventType, entity* = 0, float = 0.0f);
};

extern Career* g_career;
extern SoundScriptManager* sound_manager;

__asm__(".equ g_career,0x00427c9c");
__asm__(".equ sound_manager,0x0046b4a0");
__asm__(".equ SetInitials__6CareerG7stringx,0x0025abb0");
__asm__(".equ unpause__18SoundScriptManager,0x0031bfa8");
__asm__(".equ pause__18SoundScriptManager,0x0031bf98");
__asm__(".equ playEvent__18SoundScriptManager9EventTypeP6entityf,0x0031c380");
__asm__(".equ __7stringxPCci,0x0034d438");
__asm__(".equ _$_7stringx,0x0034d6e0");
__asm__(".equ remove_leading__7stringxPCc,0x0034ea00");
__asm__(".equ remove_trailing__7stringxPCc,0x0034eab0");

inline SoundScriptManager* SoundScriptManager::inst()
{
	return sound_manager;
}

class NameEntryMenu : public FEMultiMenu
{
	PanelQuad* box[9];
	PanelQuad* line;
	PanelQuad* name_box[3];
	PanelQuad* keys[41][2];
	bool in_game;
	TextString* high_score;
	TextString* enter_name;
	TextString* name;
	int name_count;
	bool name_entered;
	bool canceled;
	FEMenuEntry* entry[41];

public:
	virtual void Select(int entry_index);
};

void NameEntryMenu::Select(int entry_index)
{
	stringx str = name->getText();

	if(entry_index > 38)
	{
		if(entry_index == 39)// <enter>
		{	
			g_career->SetInitials(name->getText());
			name_entered = true;
			SoundScriptManager::inst()->unpause();
			SoundScriptManager::inst()->playEvent(SS_FE_ONX);
			SoundScriptManager::inst()->pause();
		}
		else
		{
			canceled = true;
			SoundScriptManager::inst()->unpause();
			SoundScriptManager::inst()->playEvent(SS_FE_ONX);
			SoundScriptManager::inst()->pause();
		}
		parent->MakeActive(0);
		return;
	}


	char tmp[4];
	for(int i=0; i<name_count; i++)
		tmp[i] = str.data()[i];
	tmp[name_count] = '\0';

	if(name_count < 3 && (entry_index < 36 || entry_index == 37))
	{
		if(entry_index < 26) tmp[name_count] = 'A'+entry_index;
		else if(entry_index < 36) tmp[name_count] = '0'+(entry_index-26);
		else tmp[name_count] = ' ';
		name_count++;
		tmp[name_count] = '\0';
		if(name_count == 3)
		{
			stringx s = name->getText();
			s.remove_surrounding_whitespace();
			if (s.length() != 0)
				setHigh(entry[39]);
		}
		SoundScriptManager::inst()->unpause();
		SoundScriptManager::inst()->playEvent(SS_FE_ONX);
		SoundScriptManager::inst()->pause();
	}
	else if(entry_index == 36)
	{
		name_count--;
		if(name_count < 0) name_count = 0;
		tmp[name_count] = '\0';
		SoundScriptManager::inst()->unpause();
		SoundScriptManager::inst()->playEvent(SS_FE_ONX);
		SoundScriptManager::inst()->pause();
	}
	else if(entry_index == 38)
	{
		name_count = 0;
		tmp[0] = '\0';
		SoundScriptManager::inst()->unpause();
		SoundScriptManager::inst()->playEvent(SS_FE_ONX);
		SoundScriptManager::inst()->pause();
	}
	else
	{
		SoundScriptManager::inst()->unpause();
		SoundScriptManager::inst()->playEvent(SS_FE_ERROR);
		SoundScriptManager::inst()->pause();
	}

	name->changeText(tmp);
}
